import json

def render(finance,inventory,timing,path):
    data=json.dumps(dict(finance=finance,inventory=inventory,timing=timing),allow_nan=False).replace('</','<\\/')
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Beyond Q — fuel-supported rollout v2.2</title>
<style>body{font:15px system-ui;margin:26px;max-width:1250px;background:#f5f7fa;color:#193147}select{padding:7px;margin:5px}canvas{width:100%;height:340px;background:white}table{border-collapse:collapse;width:100%;margin:15px 0}td,th{padding:7px;border-bottom:1px solid #ccd;text-align:right}td:first-child,th:first-child{text-align:left}.note{padding:12px;background:#e5edf5}#detail{overflow:auto}</style>
<h1>Beyond Q: separately financed, fuel-supported expansion</h1>
<p>G1–G5 OPEN. Conditional scenarios are not validated reactors or financing offers. GPU/QPU economics excluded. Mandatory He-3 retention = 0. The white paper's predecessor rule is represented by sequential_predecessors; eligible_pool is a separate relaxed parallel-project sensitivity.</p>
<label>Scenario <select id="scenario"></select></label><label>Recovery <select id="recovery"></select></label><label>Price <select id="price"></select></label><label>He-3 offtake <select id="offtake"></select></label><label>Plot <select id="metric"></select></label>
<div class="note" id="scope"></div><canvas id="plot"></canvas><div id="detail"></div><h2>Rollout comparison</h2><div id="comparison"></div>
<script>const DATA=__DATA__,$=id=>document.getElementById(id),fmt=v=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:3}):'UNRESOLVED';
const METRICS={commissioned_modules:'Operating campuses',building_modules:'Projects building',T_total_kg:'Campus tritium stocks (excludes escrow) — kg',reserved_and_transit_inventory_kg:'Reserved + transit fuel — kg',He3_product_candidate_STP_L:'He-3 product candidate — STP L/year',He3_sale_candidate_STP_L:'He-3 conditional sales allocation — STP L/year',electricity_net_MWh:'Net electricity — MWh/year',electricity_import_MWh:'Electricity imports — MWh/year',T_predecessor_fuel_sent_kg:'Donor fuel reservations — kg/year',debt_service_USD_if_capital_incomplete_is_partial:'Partial-scope independent debt service — USD/year',revenue_less_known_charges_USD:'Revenue less known charges — USD/year; NOT profit',actual_profit_USD:'Actual profit — UNRESOLVED'};
for(const [id,key] of [['scenario','scenario'],['recovery','He3_overall_recovery_assumed'],['price','price_case'],['offtake','offtake_case']])for(const v of [...new Set(DATA.finance.map(r=>r[key]))])$(id).add(new Option(id==='recovery'?100*v+'%':v,v));
for(const [key,label] of Object.entries(METRICS))$('metric').add(new Option(label,key));$('scenario').value='sequential_predecessors';$('recovery').value='0.375';
function filtered(){return DATA.finance.filter(r=>r.scenario===$('scenario').value&&r.He3_overall_recovery_assumed===Number($('recovery').value)&&r.price_case===$('price').value&&r.offtake_case===$('offtake').value).sort((a,b)=>a.year-b.year)}
const table=(heads,rows)=>'<table><tr>'+heads.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+rows.map(a=>'<tr>'+a.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</table>';
function draw(){const financial=filtered(),map=new Map(DATA.inventory.filter(r=>r.scenario===$('scenario').value).map(r=>[r.year,r]));
const rows=financial.map(r=>({...r,...map.get(r.year)})),k=$('metric').value;
$('scope').textContent=($('scenario').value==='strict_unresolved'?'Strict mode: expansion waits for missing full-cost and physical qualification evidence.':$('scenario').value==='eligible_pool'?'Relaxed parallel-project sensitivity: mature donors may fuel multiple separately financed successors before all earlier project IDs mature.':$('scenario').value==='sequential_predecessors'?'Originator-chain baseline: every earlier campus must meet the trailing operating screen before the next project is authorized.':'Control case; not a fuel-gated rollout.')+' Construction = 3 years; trailing performance window = 1 year; up to 4 concurrent projects. These are assumptions. '+($('offtake').value==='fleet_cap_stress'?'He-3 sales cap is an illustrative fleet-wide stress input.':'Full-offtake assumes customers; it is not a demand forecast.');
const canvas=$('plot'),w=canvas.clientWidth||1100,h=340,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.font='12px system-ui';
const valid=rows.filter(r=>typeof r[k]==='number'&&Number.isFinite(r[k]));if(!valid.length){c.fillText('UNRESOLVED — no numeric result; unknown is not zero.',80,60)}else{const lo=Math.min(0,...valid.map(r=>r[k])),hi=Math.max(1,...valid.map(r=>r[k]));const X=yr=>100+(yr-1)/Math.max(1,rows.length-1)*(w-120),Y=v=>300-(v-lo)/(hi-lo)*270;for(let j=0;j<=4;j++){let v=lo+(hi-lo)*j/4,y=Y(v);c.strokeStyle='#d6dee7';c.beginPath();c.moveTo(100,y);c.lineTo(w-20,y);c.stroke();c.fillText(v.toLocaleString(undefined,{maximumFractionDigits:0}),2,y)}c.strokeStyle='#247a73';c.lineWidth=2;c.beginPath();let pen=false;for(const r of rows){if(typeof r[k]!=='number'){pen=false;continue}if(pen)c.lineTo(X(r.year),Y(r[k]));else c.moveTo(X(r.year),Y(r[k]));pen=true}c.stroke();c.fillText('Year 1',100,325);c.fillText('Year '+rows.length,w-85,325)}
$('detail').innerHTML=table(['Year','Campuses','He-3 candidate L','Fuel reserved kg','Fuel received kg','Net MWh','Actual profit'],rows.filter(r=>[1,2,5,10,20,30,40,50,60].includes(r.year)).map(r=>[r.year,fmt(r.commissioned_modules??r.active_modules),fmt(r.He3_product_candidate_STP_L),fmt(r.T_predecessor_fuel_sent_kg),fmt(r.T_predecessor_fuel_received_kg),fmt(r.electricity_net_MWh),'UNRESOLVED']));
}
$('comparison').innerHTML=table(['Policy','Operating by horizon','First successor year','50th campus year','Reserve violations'],DATA.timing.map(r=>[r.scenario,fmt(r.commissioned_by_horizon),fmt(r.first_successor_commission_year),fmt(r.commissioned_50_year),fmt(r.donor_floor_violations)]));
for(const id of ['scenario','recovery','price','offtake','metric'])$(id).addEventListener('change',draw);window.addEventListener('resize',draw);draw();</script></html>'''
    path.write_text(template.replace('__DATA__',data))
